<?php
require 'vendor/autoload.php';
$container = new Illuminate\Container\Container;
Illuminate\Container\Container::setInstance($container);
$container->instance('config', new Illuminate\Config\Repository);
$action = (new ReflectionClass(App\Services\Procurement\Fixture\RunFixtureAnalysisAction::class))->newInstanceWithoutConstructor();
$fixture = (new ReflectionClass(App\Models\Procurement\Ai\Fixture::class))->newInstanceWithoutConstructor();
$failed = false;
foreach ([[false, true], [true, false]] as [$downstream, $screening]) {
    config(['crawler.downstream_enabled' => $downstream, 'ai.screening.enabled' => $screening]);
    try {
        $action->run($fixture);
        echo "FAIL: disabled stage allowed fixture run\n";
        $failed = true;
    } catch (App\Exceptions\Procurement\OperationFailed $e) {
        echo json_encode(['downstream' => $downstream, 'screening' => $screening, 'exception' => $e::class, 'message' => $e->getMessage()], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), "\n";
        $expectedFlag = $downstream ? 'AI_SCREENING_ENABLED' : 'CRAWLER_DOWNSTREAM_ENABLED';
        if (! str_contains($e->getMessage(), $expectedFlag)) {
            echo "FAIL: operator notification must identify $expectedFlag\n";
            $failed = true;
        }
    }
}
exit($failed ? 1 : 0);
PHP
